import { createHash, createHmac } from "node:crypto";
import type { GrowwConfig } from "../../config/config.js";
import type { Clock } from "../../util/clock.js";
import { BrokerAuthError } from "../BrokerPort.js";
import type { HttpFetch } from "./http.js";

/**
 * Groww access-token management. Three ways in (from Groww's official Python SDK 1.5.0, `get_access_token`):
 *  1. GROWW_ACCESS_TOKEN: a token generated by hand for the day; used as-is.
 *  2. GROWW_API_KEY + GROWW_API_SECRET ("approval" key): POST /token/api/access with
 *     {key_type: "approval", checksum: sha256(secret + timestamp), timestamp}.
 *  3. GROWW_API_KEY + GROWW_TOTP_SEED ("totp" key): POST /token/api/access with {key_type: "totp", totp}.
 * The token is held in memory only: never logged, persisted, audited or sent to Telegram.
 * UNVERIFIED: the daily expiry time (assumed 06:00 IST) and the response field name `token` (taken from the SDK).
 */
export function base32Decode(s: string): Buffer {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
  const clean = s.toUpperCase().replace(/[\s=-]/g, "");
  let bits = 0;
  let value = 0;
  const out: number[] = [];
  for (const c of clean) {
    const i = alphabet.indexOf(c);
    if (i < 0) throw new Error("invalid base32 character in TOTP seed");
    value = (value << 5) | i;
    bits += 5;
    if (bits >= 8) {
      out.push((value >>> (bits - 8)) & 0xff);
      bits -= 8;
    }
  }
  return Buffer.from(out);
}

/** RFC 6238 TOTP (HMAC-SHA1, 30 s step). */
export function totp(key: Buffer, at: Date, digits = 6, stepSec = 30): string {
  const counter = Math.floor(at.getTime() / 1000 / stepSec);
  const msg = Buffer.alloc(8);
  msg.writeBigUInt64BE(BigInt(counter));
  const h = createHmac("sha1", key).update(msg).digest();
  const off = h[h.length - 1]! & 0x0f;
  const code = ((h[off]! & 0x7f) << 24) | (h[off + 1]! << 16) | (h[off + 2]! << 8) | h[off + 3]!;
  return String(code % 10 ** digits).padStart(digits, "0");
}

export function approvalChecksum(secret: string, timestamp: number): string {
  return createHash("sha256").update(secret + String(timestamp)).digest("hex");
}

/** Last 06:00 IST at or before `d`. */
export function lastTokenReset(d: Date): number {
  const istMs = d.getTime() + 330 * 60_000;
  const day = Math.floor(istMs / 86_400_000) * 86_400_000;
  let reset = day + 6 * 3_600_000;
  if (reset > istMs) reset -= 86_400_000;
  return reset - 330 * 60_000;
}

export class GrowwTokenManager {
  #token: string | undefined;
  #issuedAt = 0;

  constructor(
    private readonly cfg: GrowwConfig,
    private readonly http: HttpFetch,
    private readonly clock: Clock,
  ) {
    if (!cfg.accessToken && !(cfg.apiKey && (cfg.apiSecret || cfg.totpSeed))) {
      throw new BrokerAuthError("Groww credentials missing: set GROWW_ACCESS_TOKEN, or GROWW_API_KEY with GROWW_API_SECRET or GROWW_TOTP_SEED");
    }
  }

  invalidate(): void {
    this.#token = undefined;
  }

  async token(): Promise<string> {
    const now = this.clock.now();
    if (this.#token && this.#issuedAt >= lastTokenReset(now)) return this.#token;
    if (this.cfg.accessToken) {
      this.#token = this.cfg.accessToken.reveal();
      this.#issuedAt = now.getTime();
      return this.#token;
    }
    const apiKey = this.cfg.apiKey!.reveal();
    let body: Record<string, unknown>;
    if (this.cfg.apiSecret) {
      const ts = Math.floor(now.getTime() / 1000);
      body = { key_type: "approval", checksum: approvalChecksum(this.cfg.apiSecret.reveal(), ts), timestamp: ts };
    } else {
      body = { key_type: "totp", totp: totp(base32Decode(this.cfg.totpSeed!.reveal()), now) };
    }
    let res;
    try {
      res = await this.http(`${this.cfg.baseUrl}/token/api/access`, {
        method: "POST",
        headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json", Accept: "application/json", "x-api-version": "1.0" },
        body: JSON.stringify(body),
        signal: AbortSignal.timeout(this.cfg.requestTimeoutMs),
      });
    } catch (e) {
      throw new BrokerAuthError(`Groww token request failed: network (${(e as Error)?.name ?? "Error"})`);
    }
    let data: Record<string, unknown> = {};
    try {
      data = (await res.json()) as Record<string, unknown>;
    } catch {
      /* fall through */
    }
    const token = typeof data.token === "string" ? data.token : undefined;
    if (!res.ok || !token) throw new BrokerAuthError(`Groww token request failed: HTTP ${res.status}`, String(res.status));
    this.#token = token;
    this.#issuedAt = now.getTime();
    return token;
  }
}
